def solve_formula(grid_in, bg_val, fill_val):
    rows = len(grid_in)
    cols = len(grid_in[0])

    non_bg = [(r, c) for r in range(rows) for c in range(cols) if grid_input[r][c] != bg_val]

    if not non_bg:
        return [row[:] for row in grid_in]

    min_r, max_r = min(r for r, _ in non_bg), max(r for r, _ in non_bg)
    min_c, max_c = min(c for _, c in non_bg), max(c for _, c in non_bg)

    result = [row[:] for row in grid_in]

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if grid_in[r][c] == bg_val:
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if min_r <= nr <= max_r and min_c <= nc <= max_c:
                        if grid_in[nr][nc] != bg_val:
                            result[r][c] = fill_val
                            break

    return result

